+maximumFrameWords: -> Int => 16000000
+
+# Reserve the checksum and every remaining row header before admitting a
+# payload. Subtraction keeps untrusted counts from overflowing the budget.
+capturedRowFits wordCount: Int, payloadCount: Int, remainingRows: Int -> Bool {
+    wordCount < 9 or wordCount > maximumFrameWords() or payloadCount < 72
+        or remainingRows < 0 or remainingRows > (maximumFrameWords() - 41) / 2
+        -> if { false -> return }
+    maximumFrameWords() - wordCount - 32 => available
+    available < (remainingRows + 1) * 2 -> if { false -> return }
+    payloadCount <= available - (remainingRows + 1) * 2
+}
+
+appendSkippedRow words: mut [UInt64; ~], status: Int -> Unit {
+    words -> push(UInt64(status))
+    words -> push(0)
+}
+
+appendGenerationRow encoded: move owners.EncodedOwnerCalls, words: mut [UInt64; ~], remainingRows: Int -> Int {
+    encoded.status != 0 -> if {
+        words -> appendSkippedRow(encoded.status)
+        encoded.status -> return
+    }
+    not capturedRowFits(words -> len, encoded.words -> len, remainingRows) -> if {
+        words -> appendSkippedRow(24)
+        24 -> return
+    }
+    words -> push(0)
+    words -> push(UInt64(encoded.words -> len))
+    encoded.words -> each word { words -> push(word) }
+    0
+}
