+# Mismatches retain load's framing/checksum diagnostics before status 33.
+verifyStagedFrame words: ref [UInt64; ~], temporary: Text -> Int uses File {
+    temporary -> libraryInterfaces.readSourcePath -> when {
+        Err(code) { code -> return }
+        Ok(mapped) {
+            (mapped -> len) == UIntSize(words -> len) * 8 -> if {
